function art_pc($i='b'){ $f=''; foreach([[165,60],[165,120],[165,180]] as $k=>$c){ $f.='<circle cx="'.$c[0].'" cy="'.$c[1].'" r="25" fill="none" stroke="url(#'.$i.'r)" stroke-width="5"/><circle cx="'.$c[0].'" cy="'.$c[1].'" r="6" fill="#7aa8ff"/>'; }
 return '<svg viewBox="0 0 420 270" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><linearGradient id="'.$i.'r" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#b44bff"/><stop offset="1" stop-color="#2fa8ff"/></linearGradient><linearGradient id="'.$i.'m" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#0a1b5c"/><stop offset="1" stop-color="#3a8cff"/></linearGradient><radialGradient id="'.$i.'g"><stop offset="0" stop-color="#8a4bff" stop-opacity=".55"/><stop offset="1" stop-color="#8a4bff" stop-opacity="0"/></radialGradient></defs><ellipse cx="210" cy="240" rx="200" ry="26" fill="url(#'.$i.'g)"/><rect x="18" y="62" width="170" height="108" rx="6" fill="#0a0f1d" stroke="#6b7a99" stroke-width="3"/><rect x="25" y="69" width="156" height="94" fill="url(#'.$i.'m)"/><path d="M95 170h20l6 26H89z" fill="#2b3550"/><rect x="62" y="196" width="76" height="6" rx="3" fill="#4b5878"/><rect x="215" y="14" width="150" height="230" rx="10" fill="#0b1020" stroke="#7a5cff" stroke-width="3"/><rect x="224" y="24" width="132" height="210" rx="6" fill="#120c2e"/><g transform="translate(125 0)">'.$f.'</g><rect x="262" y="214" width="56" height="5" rx="2" fill="#2fa8ff"/></svg>'; }
function art_head($i='c'){ $k=''; for($r=0;$r<3;$r++)for($q=0;$q<9;$q++)$k.='<rect x="'.(222+$q*20).'" y="'.(150+$r*20).'" width="16" height="15" rx="3" fill="#1d2433"/>';
 return '<svg viewBox="0 0 420 270" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><radialGradient id="'.$i.'g"><stop offset="0" stop-color="#ffffff" stop-opacity=".55"/><stop offset="1" stop-color="#ffffff" stop-opacity="0"/></radialGradient></defs><ellipse cx="220" cy="236" rx="200" ry="28" fill="url(#'.$i.'g)"/><path d="M56 150V120a84 84 0 0 1 168 0v30" fill="none" stroke="#10151f" stroke-width="14" stroke-linecap="round"/><rect x="38" y="130" width="40" height="76" rx="18" fill="#171d2b" stroke="#394560" stroke-width="2"/><rect x="202" y="130" width="40" height="76" rx="18" fill="#171d2b" stroke="#394560" stroke-width="2"/><rect x="208" y="140" width="10" height="56" rx="5" fill="#2f7df6" opacity=".7"/><rect x="204" y="132" width="196" height="108" rx="10" fill="#0e131e" transform="rotate(-6 300 186)"/><g transform="rotate(-6 300 186)">'.$k.'</g><path d="M96 232c-6-30 22-48 50-40 28 8 34 34 14 46-22 12-58 8-64-6z" fill="#161b27" stroke="#394560" stroke-width="2"/></svg>'; }
